/// Marketplace chrome copy (header, filters, buttons, products page).
///
/// English strings are the source of truth for tests. Other locales, especially
/// Polish (`pl`) and Turkish (`tr`), are filled in here and merged into
/// [kTranslationsMap] so FlutterFlow keys like `x5fioudz` ("Buy") pick them up.
library;

Map<String, String> _l({
  required String en,
  required String pl,
  required String tr,
  required String de,
  required String cs,
  required String sk,
  required String uk,
  required String be,
  required String lt,
  required String ru,
}) =>
    {
      'en': en,
      'pl': pl,
      'tr': tr,
      'de': de,
      'cs': cs,
      'sk': sk,
      'uk': uk,
      'be': be,
      'lt': lt,
      'ru': ru,
    };

Map<String, String> _d(String en, {String? pl, String? tr}) => _l(
      en: en,
      pl: pl ?? en,
      tr: tr ?? en,
      de: en,
      cs: en,
      sk: en,
      uk: en,
      be: en,
      lt: en,
      ru: en,
    );

