/// Merges FlutterFlow groups with [kUiTranslations] and copies full-language
/// rows onto generated keys whose English text matches a chrome string
/// (so `x5fioudz` / "Buy" becomes "Satın Al" in Turkish).
Map<String, Map<String, String>> mergeTranslations(
  Iterable<Map<String, Map<String, String>>> groups,
) {
  final merged = <String, Map<String, String>>{};
  for (final group in groups) {
    merged.addAll(group);
  }
  merged.addAll(kUiTranslations);

  final byEnglish = <String, Map<String, String>>{};
  for (final row in kUiTranslations.values) {
    final en = row['en'];
    if (en == null || en.trim().length < 3) continue;
    byEnglish[en] = row;
    byEnglish[en.replaceAll('\n', '').trim()] = row;
  }

  for (final key in merged.keys.toList()) {
    if (kUiTranslations.containsKey(key)) continue;
    final current = merged[key]!;
    final en = current['en'];
    if (en == null) continue;
    final src = byEnglish[en] ?? byEnglish[en.replaceAll('\n', '').trim()];
    if (src == null) continue;
    merged[key] = {...src, 'en': en};
  }
  return merged;
}
